, '') AS applicant_race_name_3, COALESCE(p.applicant_race_3::text, '') AS applicant_race_3, COALESCE(p.applicant_race_name_4::text, '') AS applicant_race_name_4, COALESCE(p.applicant_race_4::text, '') AS applicant_race_4, COALESCE(p.applicant_race_name_5::text, '') AS applicant_race_name_5, COALESCE(p.applicant_race_5::text, '') AS applicant_race_5, COALESCE(p.co_applicant_race_name_1::text, '') AS co_applicant_race_name_1, COALESCE(p.co_applicant_race_1::text, '') AS co_applicant_race_1, COALESCE(p.co_applicant_race_name_2::text, '') AS co_applicant_race_name_2, COALESCE(p.co_applicant_race_2::text, '') AS co_applicant_race_2, COALESCE(p.co_applicant_race_name_3::text, '') AS co_applicant_race_name_3, COALESCE(p.co_applicant_race_3::text, '') AS co_applicant_race_3, COALESCE(p.co_applicant_race_name_4::text, '') AS co_applicant_race_name_4, COALESCE(p.co_applicant_race_4::text, '') AS co_applicant_race_4, COALESCE(p.co_applicant_race_name_5::text, '') AS co_applicant_race_name_5, COALESCE(p.co_applicant_race_5::text, '') AS co_applicant_race_5, COALESCE(p.applicant_sex_name::text, '') AS applicant_sex_name, COALESCE(p.applicant_sex::text, '') AS applicant_sex, COALESCE(p.co_applicant_sex_name::text, '') AS co_applicant_sex_name, COALESCE(p.co_applicant_sex::text, '') AS co_applicant_sex, COALESCE(p.applicant_income_000s::text, '') AS applicant_income_000s, COALESCE(p.purchaser_type_name::text, '') AS purchaser_type_name, COALESCE(p.purchaser_type::text, '') AS purchaser_type, COALESCE(p.denial_reason_name_1::text, '') AS denial_reason_name_1, COALESCE(p.denial_reason_1::text, '') AS denial_reason_1, COALESCE(p.denial_reason_name_2::text, '') AS denial_reason_name_2, COALESCE(p.denial_reason_2::text, '') AS denial_reason_2, COALESCE(p.denial_reason_name_3::text, '') AS denial_reason_name_3, COALESCE(p.denial_reason_3::text, '') AS denial_reason_3, COALESCE(to_char(p.rate_spread, 'FM00.00'), '') AS rate_spread, COALESCE(p.hoepa_status_name::text, '') AS hoepa_status_